      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 240
      },
      "maxItems": 20
    },
    "sub_agent_id": {
      "type": "string",
      "minLength": 1,
      "maxLength": 160
    },
    "feedback": {
