        "type": "string"
      },
      "maxItems": 12
    },
    "source": {
      "type": "string",
      "maxLength": 120
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 50
    },
    "record": {
      "$ref": "#/$defs/memory_record"
    }
  }
}

